<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class DormitoryStudentController extends Controller{
public function my(Request $r){abort_unless($r->user()->hasRole('student')||$r->user()->isSuperAdmin(),403);$sid=$r->user()->student_id??null;abort_if(!$sid,404,'Профиль студента не связан');$stay=DB::table('dormitory_stays as st')->join('dormitory_places as p','p.id','=','st.dormitory_place_id')->join('dormitory_rooms as rm','rm.id','=','p.dormitory_room_id')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->where(['st.student_id'=>$sid,'st.status'=>'active'])->select('st.*','p.number place_number','rm.id room_id','rm.number room_number','b.name building_name','b.address')->first();$charges=$stay?DB::table('dormitory_charges')->where('dormitory_stay_id',$stay->id)->orderByDesc('period')->get():collect();$requests=$stay?DB::table('dormitory_maintenance_requests')->where('student_id',$sid)->orderByDesc('id')->get():collect();$notifications=DB::table('dormitory_notifications')->where('student_id',$sid)->orderByDesc('created_at')->limit(30)->get();if($stay)$this->sync($sid,$stay);return view('dormitory.my',compact('stay','charges','requests','notifications'));}
public function request(Request $r){abort_unless($r->user()->hasRole('student'),403);$sid=$r->user()->student_id??null;$stay=DB::table('dormitory_stays as st')->join('dormitory_places as p','p.id','=','st.dormitory_place_id')->where(['st.student_id'=>$sid,'st.status'=>'active'])->select('st.*','p.dormitory_room_id')->first();abort_if(!$stay,422,'Нет активного проживания');$d=$r->validate(['category'=>'required|string|max:100','priority'=>'required|in:normal,high','description'=>'required|string|max:5000']);DB::table('dormitory_maintenance_requests')->insert($d+['dormitory_room_id'=>$stay->dormitory_room_id,'student_id'=>$sid,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
private function sync($sid,$stay){$charges=DB::table('dormitory_charges')->where('dormitory_stay_id',$stay->id)->whereIn('status',['unpaid','partial'])->get();foreach($charges as $x){$fp='charge-'.$x->id.'-'.$x->status.'-'.$x->paid_amount;DB::table('dormitory_notifications')->updateOrInsert(['fingerprint'=>$fp],['student_id'=>$sid,'type'=>'charge','title'=>'Оплата общежития','message'=>'Период '.$x->period.': осталось '.((float)$x->amount-(float)$x->paid_amount),'updated_at'=>now(),'created_at'=>now()]);}$a=DB::table('dormitory_absences')->where('dormitory_stay_id',$stay->id)->whereNull('returned_at')->whereNotNull('expected_back_at')->where('expected_back_at','<',now())->first();if($a)DB::table('dormitory_notifications')->updateOrInsert(['fingerprint'=>'absence-'.$a->id.'-overdue'],['student_id'=>$sid,'type'=>'absence','title'=>'Отметьте возвращение в общежитие','message'=>'Ожидаемая дата возвращения прошла. Обратитесь к коменданту.','updated_at'=>now(),'created_at'=>now()]);}}
